[ExtensionOf(classStr(PriceDiscPolicyDialog))]
final class AVAPriceDiscPolicyDialog_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
protected boolean findPolicies()
{
    AVASalesParameters      avaSalesParameters = AVASalesParameters::find();
    boolean   ret = next findPolicies();

    if (avaSalesParameters.PriceSearch == NoYes::Yes)
    {
        ret = false;
    }

    return ret;
}
